const D={up:[1,0],down:[-1,0],left:[0,-1],right:[0,1]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],left:[0,0,0.7071068,0.7071068],right:[0,0,-0.7071068,0.7071068]};
const dist=s=>(2-s.r)+(2-s.c);
export function initialState(){return {r:0,c:0,moves:0,hint:null,msg:'Reach the orange goal square.',won:false};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const s={...state};const a=event.action;
if(a==='hint'){if(s.won)return s;s.hint=s.c<2?'right':'up';s.msg='Hint: move '+s.hint+' to get one step closer.';return s;}
const d=D[a];if(!d)return s;
if(s.won){s.msg='Goal reached! Press Reset to play again.';return s;}
const r=s.r+d[0],c=s.c+d[1];
if(r<0||r>2||c<0||c>2){s.msg='That move would leave the board.';s.hint=null;return s;}
s.r=r;s.c=c;s.moves+=1;s.hint=null;
if(dist(s)===0){s.won=true;s.msg='You reached the goal in '+s.moves+' moves. The shortest route is 4 moves.'+(s.moves===4?' Perfect!':'');}
else s.msg=dist(s)+' steps to go.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const x=(s.c-1)*1.1,z=(1-s.r)*1.1,y=s.won?0.52:0.46;
const n={tokenBall:{position:[x,y,z]},hintArrow:{visible:!!s.hint&&!s.won,position:[x,y,z]}};
if(s.hint)n.hintArrow.quaternion=Q[s.hint];
return {nodes:n,readouts:{steps:dist(s),moves:s.moves},goal:{status:s.won?'won':'playing',message:s.msg}};}
